import torch
import torch.nn as nn
from transformers.pytorch_utils import ALL_LAYERNORM_LAYERS


def rms_norm(hidden_states, eps=1e-5):
    input_dtype = hidden_states.dtype
    hidden_states = hidden_states.to(torch.float32)
    variance = hidden_states.pow(2).mean(-1, keepdim=True)
    hidden_states = hidden_states * torch.rsqrt(variance + eps)

    return hidden_states.to(input_dtype)


class RMSNorm(nn.Module):
    def __init__(self, hidden_size, std=1.0, eps=1e-5):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size)*std)
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        return self.weight * rms_norm(hidden_states, self.variance_epsilon)


ALL_LAYERNORM_LAYERS.append(RMSNorm)

from transformers.models.whisper.modeling_whisper import WhisperModel, WhisperEncoder
from transformers import WhisperConfig, WhisperFeatureExtractor


class WhisperAudioTowerConfig(WhisperConfig):
    pass


class WhisperAudioTower(WhisperModel):
    config_class = WhisperAudioTowerConfig

    def __init__(self, config: WhisperAudioTowerConfig):
        super(WhisperModel, self).__init__(config)

        self.encoder = WhisperEncoder(config)
        self.post_init()

        self.audio_processor = WhisperFeatureExtractor.from_pretrained(self.name_or_path)

    def get_input_embeddings(self):
        return self.encoder.conv1

    def forward(self, audios):
        return self.encoder(audios)[0]

    @property
    def hidden_size(self):
        return self.config.d_model

from transformers import (
    CLIPVisionModel, CLIPImageProcessor, CLIPVisionConfig
)


class CLIPVisionTowerConfig(CLIPVisionConfig):
    select_layer = -2


class CLIPVisionTower(CLIPVisionModel):
    config_class = CLIPVisionTowerConfig

    def __init__(self, config: CLIPVisionTowerConfig):
        super().__init__(config)

        self.image_processor = CLIPImageProcessor.from_pretrained(self.name_or_path)
        self.image_processor.output_size = self.image_processor.size["shortest_edge"]

    def forward(self, images):
        image_forward_outs = super().forward(images, output_hidden_states=True)
        image_features = image_forward_outs.hidden_states[self.config.select_layer]
        image_features_cls = image_features[:, 0]
        image_features_pch = image_features[:, 1:]

        return image_features_cls, image_features_pch

    def encode(self, inputs_embeds, attention_mask):
        inputs_embeds = self.vision_model.pre_layrnorm(inputs_embeds)
        inputs_embeds = self.vision_model.encoder(
            inputs_embeds=inputs_embeds, attention_mask=attention_mask,
            return_dict=True, output_hidden_states=True
        ).hidden_states[self.config.select_layer]

        return inputs_embeds

    @property
    def hidden_size(self):
        return self.config.hidden_size

    @property
    def num_patches_per_side(self):
        return self.config.image_size // self.config.patch_size

    @property
    def num_patches(self):
        return (self.config.image_size // self.config.patch_size) ** 2

from transformers import (
    SiglipVisionModel, SiglipImageProcessor, SiglipVisionConfig
)


class SiglipVisionTowerConfig(SiglipVisionConfig):
    select_layer = -2


class SiglipVisionTower(SiglipVisionModel):
    config_class = SiglipVisionTowerConfig

    def __init__(self, config: SiglipVisionTowerConfig):
        super().__init__(config)

        self.image_processor = SiglipImageProcessor.from_pretrained(self.name_or_path)
        self.image_processor.output_size = self.image_processor.size["height"]

    def forward(self, images):
        image_forward_outs = super().forward(images, output_hidden_states=True)
        image_features_cls = image_forward_outs.pooler_output
        image_features_pch = image_forward_outs.hidden_states[self.config.select_layer]

        return image_features_cls, image_features_pch

    @property
    def hidden_size(self):
        return self.config.hidden_size

    @property
    def num_patches_per_side(self):
        return self.config.image_size // self.config.patch_size

    @property
    def num_patches(self):
        return (self.config.image_size // self.config.patch_size) ** 2

import re
from torch import nn, Tensor
from torch.nn import functional as F


class MLP(nn.Module):
    def __init__(self, arch: str, d_mm: int, d_llm: int):
        super().__init__()

        if arch == 'linear':
            self.model = nn.Linear(d_mm, d_llm)
        elif arch.startswith('mlp'):
            mlp_gelu_match = re.match(r'^mlp(\d+)x_gelu$', arch)
            mlp_depth = int(mlp_gelu_match.group(1))
            modules = [nn.Linear(d_mm, d_llm)]
            for _ in range(1, mlp_depth):
                modules.append(nn.GELU())
                modules.append(nn.Linear(d_llm, d_llm))
            self.model = nn.Sequential(*modules)

        else:
            raise NotImplementedError(f'Unknown projector arch: {arch}')

    def forward(self, x):
        return self.model(x)


class Linear(nn.Linear):
    def __init__(self, in_features: int, out_features: int, bias: bool = True, device=None, dtype=None) -> None:
        super().__init__(in_features, out_features, bias, device, dtype)

        self.dtype = dtype

    def forward(self, input: Tensor) -> Tensor:
        return F.linear(
            input.to(self.dtype), self.weight.to(self.dtype),
            self.bias.to(self.dtype) if self.bias is not None else None
        )
